const cfg = $('Init Run').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.test_id);

const CATS = ["ROLE_DEVIATION","HALLUCINATION","PROMPT_INJECTION","PRIVACY","OVER_REFUSAL"];
const total = rows.length;
const isPass = r => r.result === "PASS";
const isFail = r => r.result === "FAIL";
const isReview = r => r.result === "REVIEW_REQUIRED";

const passed = rows.filter(isPass).length;
const failed = rows.filter(isFail).length;
const review = rows.filter(isReview).length;
const overallPassRate = total ? Number((passed / total).toFixed(4)) : 0;
const overallScore = total ? Number(((passed / total) * 100).toFixed(2)) : 0;

const failureByCat = {};
const passRateByCat = {};
const categoryResults = [];
for (const c of CATS) {
  const inCat = rows.filter(r => r.risk_category === c);
  const catPass = inCat.filter(isPass).length;
  const catFail = inCat.filter(isFail).length;
  const catReview = inCat.filter(isReview).length;
  failureByCat[c] = catFail;
  passRateByCat[c] = inCat.length ? Number((catPass / inCat.length).toFixed(4)) : 0;
  categoryResults.push({ category: c, total: inCat.length, pass: catPass, fail: catFail, review_required: catReview, pass_rate: passRateByCat[c] });
}

const highOrCritical = rows.filter(r => (isFail(r)) && (r.severity === "HIGH" || r.severity === "CRITICAL")).length;
const countFailInCat = c => rows.filter(r => r.risk_category === c && isFail(r)).length;

const criticalFindings = rows
  .filter(r => isFail(r) && (r.severity === "HIGH" || r.severity === "CRITICAL"))
  .map(r => ({ test_id: r.test_id, risk_category: r.risk_category, severity: r.severity, reason: r.reason, evidence: r.evidence }));

const failedTests = rows.filter(isFail).map(r => ({ test_id: r.test_id, risk_category: r.risk_category, severity: r.severity, reason: r.reason }));

const mainFailurePatterns = CATS
  .filter(c => failureByCat[c] > 1)
  .map(c => ({ risk_category: c, failure_count: failureByCat[c] }));

const recommendedImprovements = Array.from(new Set(
  rows.filter(r => (isFail(r) || isReview(r)) && r.recommendation).map(r => r.recommendation)
));

const humanReviewItems = rows
  .filter(r => r.human_review_required === true || r.human_review_required === "true" || isReview(r))
  .map(r => ({ test_id: r.test_id, risk_category: r.risk_category, reason: r.reason, confidence: r.confidence }));

const report = {
  run_id: cfg.run_id,
  agent_name: cfg.agent_name,
  generated_at: $now.toISO(),
  overall_score: overallScore,
  disclaimer: "These results represent risk signals requiring review, not a definitive security certification.",
  summary: { total, pass: passed, fail: failed, review_required: review },
  metrics: {
    total_tests: total,
    passed_tests: passed,
    failed_tests: failed,
    review_required_tests: review,
    overall_pass_rate: overallPassRate,
    failure_count_by_category: failureByCat,
    pass_rate_by_category: passRateByCat,
    high_or_critical_risk_count: highOrCritical,
    over_refusal_count: countFailInCat("OVER_REFUSAL"),
    hallucination_failure_count: countFailInCat("HALLUCINATION"),
    prompt_injection_failure_count: countFailInCat("PROMPT_INJECTION"),
    privacy_failure_count: countFailInCat("PRIVACY"),
    role_deviation_failure_count: countFailInCat("ROLE_DEVIATION"),
  },
  category_results: categoryResults,
  failed_tests: failedTests,
  critical_findings: criticalFindings,
  main_failure_patterns: mainFailurePatterns,
  recommended_improvements: recommendedImprovements,
  human_review_items: humanReviewItems,
};

return [{ json: report }];

const tc = $('Mark Start').item.json;
const started = Number(tc.started_ms) || $now.toMillis();
const responseTime = Math.max(0, $now.toMillis() - started);

const raw = $json || {};
let executionError = "";
let answer = "";

if (raw.error) {
  executionError = typeof raw.error === "string" ? raw.error : JSON.stringify(raw.error);
}

let payload = raw;
let statusCode = raw.statusCode;
if (raw && typeof raw === "object" && raw.body !== undefined) { payload = raw.body; }
else if (raw && typeof raw === "object" && raw.data !== undefined && (raw.statusCode !== undefined || raw.headers !== undefined)) { payload = raw.data; }

if (!executionError && statusCode !== undefined && (statusCode < 200 || statusCode >= 300)) {
  executionError = "HTTP status " + statusCode;
}

if (typeof payload === "string") {
  const trimmed = payload.trim();
  if (trimmed === "") {
    if (!executionError) executionError = "Empty response from target agent";
  } else {
    try {
      const parsed = JSON.parse(trimmed);
      payload = parsed;
    } catch (e) {
      answer = trimmed;
    }
  }
}

if (!answer && payload && typeof payload === "object") {
  if (payload.data && typeof payload.data.message === "string") {
    answer = payload.data.message;
  } else if (typeof payload.answer === "string") {
    answer = payload.answer;
  } else if (typeof payload.message === "string") {
    answer = payload.message;
  } else if (typeof payload.output === "string") {
    answer = payload.output;
  } else if (typeof payload.response === "string") {
    answer = payload.response;
  } else if (typeof payload.text === "string") {
    answer = payload.text;
  } else if (!executionError) {
    executionError = "Response did not contain an 'answer' field";
    answer = JSON.stringify(payload);
  }
}

if (!answer && !executionError) {
  executionError = "Empty response from target agent";
}

return {
  test_id: tc.test_id,
  risk_category: tc.risk_category,
  test_question: tc.test_question,
  expected_behavior: tc.expected_behavior,
  failure_condition: tc.failure_condition,
  severity: tc.severity,
  actual_response: answer || "",
  execution_error: executionError,
  response_time_ms: responseTime,
};

